class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int], k: int) -> int:
        pos = neg = 0
        for a, b in zip(nums1, nums2):
            d = b - a
            if d > 0: pos += d
            else: neg -= d
        if pos != neg: return -1
        if k == 0: return 0 if pos == 0 else -1
        for a, b in zip(nums1, nums2):
            if (b - a) % k: return -1
        return pos // k

