        long pos = 0, neg = 0;
        for (int i = 0; i < nums1.length; i++) {
            long d = nums2[i] - nums1[i];
            if (d > 0) pos += d; else neg -= d;
        }
        if (pos != neg) return -1;
        if (k == 0) return pos == 0 ? 0 : -1;
        for (int i = 0; i < nums1.length; i++)
